pragma solidity ^0.8.0;

/**
 * @title Ownable
 * @dev Basic ownership contract
 */
contract Ownable {
    address public owner;
    
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    
    modifier onlyOwner() {
        require(msg.sender == owner, "Ownable: caller is not the owner");
        _;
    }
    
    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }
}

/**
 * @title AggregatorV3Interface
 * @dev Chainlink price feed interface
 */
interface AggregatorV3Interface {
    function decimals() external view returns (uint8);
    
    function latestRoundData()
        external
        view
        returns (
            uint80 roundId,
            int256 answer,
            uint256 startedAt,
            uint256 updatedAt,
            uint80 answeredInRound
        );
}

/**
 * @title IERC20
 * @dev ERC20 token interface for getting token info
 */
interface IERC20 {
    function decimals() external view returns (uint8);
    function symbol() external view returns (string memory);
}

/**
 * @title PairVault Interface
 * @dev Interface for vault contract with dynamic token support
 */
interface IPairVault {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint256 reserve0, uint256 reserve1);
}

/**
 * @title MultiTokenPriceOracle
 * @dev Universal oracle contract supporting multiple tokens across different chains
 */
contract MultiTokenPriceOracle is Ownable {
    
    // Struct to store token oracle configuration
    struct TokenOracle {
        address oracleAddress;      // Chainlink price feed address
        bool isActive;              // Whether this oracle is active
        uint256 lastUpdate;         // Last time oracle was updated
    }
    
    // Mapping: token address => TokenOracle
    mapping(address => TokenOracle) public tokenOracles;
    
    // Array to keep track of all supported tokens
    address[] public supportedTokens;
    
    // Mapping to check if token is already added
    mapping(address => bool) public isTokenSupported;
    
    // Maximum age for price data (default 2 hours)
    uint256 public maxAge = 2 hours;
    
    // Fallback oracle for USD pricing (if needed)
    address public usdOracle;
    
    // Events
    event TokenOracleAdded(address indexed token, address indexed oracle);
    event TokenOracleUpdated(address indexed token, address indexed oldOracle, address indexed newOracle);
    event TokenOracleRemoved(address indexed token);
    event MaxAgeUpdated(uint256 oldMaxAge, uint256 newMaxAge);
    
    /**
     * @dev Constructor
     */
    constructor() {
        owner = msg.sender;
    }
    
    /**
     * @dev Add a new token oracle
     * @param tokenAddress Address of the token
     * @param oracleAddress Address of the Chainlink price feed
     */
    function addTokenOracle(address tokenAddress, address oracleAddress) external onlyOwner {
        require(tokenAddress != address(0), "Invalid token address");
        require(oracleAddress != address(0), "Invalid oracle address");
        require(!isTokenSupported[tokenAddress], "Token already supported");
        
        tokenOracles[tokenAddress] = TokenOracle({
            oracleAddress: oracleAddress,
            isActive: true,
            lastUpdate: block.timestamp
        });
        
        supportedTokens.push(tokenAddress);
        isTokenSupported[tokenAddress] = true;
        
        emit TokenOracleAdded(tokenAddress, oracleAddress);
    }
    
    /**
     * @dev Add multiple token oracles in batch
     * @param tokenAddresses Array of token addresses
     * @param oracleAddresses Array of corresponding oracle addresses
     */
    function addTokenOraclesBatch(
        address[] calldata tokenAddresses, 
        address[] calldata oracleAddresses
    ) external onlyOwner {
        require(tokenAddresses.length == oracleAddresses.length, "Arrays length mismatch");
        
        for (uint256 i = 0; i < tokenAddresses.length; i++) {
            if (!isTokenSupported[tokenAddresses[i]] && 
                tokenAddresses[i] != address(0) && 
                oracleAddresses[i] != address(0)) {
                
                tokenOracles[tokenAddresses[i]] = TokenOracle({
                    oracleAddress: oracleAddresses[i],
                    isActive: true,
                    lastUpdate: block.timestamp
                });
                
                supportedTokens.push(tokenAddresses[i]);
                isTokenSupported[tokenAddresses[i]] = true;
                
                emit TokenOracleAdded(tokenAddresses[i], oracleAddresses[i]);
            }
        }
    }
    
    /**
     * @dev Update an existing token oracle
     * @param tokenAddress Address of the token
     * @param newOracleAddress New oracle address
     */
    function updateTokenOracle(address tokenAddress, address newOracleAddress) external onlyOwner {
        require(isTokenSupported[tokenAddress], "Token not supported");
        require(newOracleAddress != address(0), "Invalid oracle address");
        
        address oldOracle = tokenOracles[tokenAddress].oracleAddress;
        tokenOracles[tokenAddress].oracleAddress = newOracleAddress;
        tokenOracles[tokenAddress].lastUpdate = block.timestamp;
        
        emit TokenOracleUpdated(tokenAddress, oldOracle, newOracleAddress);
    }
    
    /**
     * @dev Activate or deactivate a token oracle
     * @param tokenAddress Address of the token
     * @param active New active status
     */
    function setTokenOracleStatus(address tokenAddress, bool active) external onlyOwner {
        require(isTokenSupported[tokenAddress], "Token not supported");
        tokenOracles[tokenAddress].isActive = active;
    }
    
    /**
     * @dev Remove a token oracle
     * @param tokenAddress Address of the token to remove
     */
    function removeTokenOracle(address tokenAddress) external onlyOwner {
        require(isTokenSupported[tokenAddress], "Token not supported");
        
        tokenOracles[tokenAddress].isActive = false;
        isTokenSupported[tokenAddress] = false;
        
        // Remove from supportedTokens array
        for (uint256 i = 0; i < supportedTokens.length; i++) {
            if (supportedTokens[i] == tokenAddress) {
                supportedTokens[i] = supportedTokens[supportedTokens.length - 1];
                supportedTokens.pop();
                break;
            }
        }
        
        emit TokenOracleRemoved(tokenAddress);
    }
    
    /**
     * @dev Get the price of a token in USD (scaled to 18 decimals)
     * @param tokenAddress Address of the token
     * @return scaledPrice The price in USD with 18 decimals
     */
    function getTokenPrice(address tokenAddress) public view returns (uint256) {
        require(isTokenSupported[tokenAddress], "Token not supported");
        
        TokenOracle memory oracle = tokenOracles[tokenAddress];
        require(oracle.isActive, "Oracle not active");
        
        (
            uint80 roundId,
            int256 price,
            ,
            uint256 updatedAt,
            uint80 answeredInRound
        ) = AggregatorV3Interface(oracle.oracleAddress).latestRoundData();
        
        require(block.timestamp - updatedAt < maxAge, "Price data is stale");
        require(price > 0, "Invalid price");
        require(answeredInRound >= roundId, "Stale round data");
        
        uint8 decimals = AggregatorV3Interface(oracle.oracleAddress).decimals();
        uint256 scaledPrice;
        
        if (decimals < 18) {
            scaledPrice = uint256(price) * 10**(18 - decimals);
        } else if (decimals > 18) {
            scaledPrice = uint256(price) / 10**(decimals - 18);
        } else {
            scaledPrice = uint256(price);
        }
        
        return scaledPrice;
    }
    
    /**
     * @dev Get prices for multiple tokens
     * @param tokenAddresses Array of token addresses
     * @return prices Array of prices in USD with 18 decimals
     */
    function getTokenPrices(address[] calldata tokenAddresses) external view returns (uint256[] memory) {
        uint256[] memory prices = new uint256[](tokenAddresses.length);
        
        for (uint256 i = 0; i < tokenAddresses.length; i++) {
            prices[i] = getTokenPrice(tokenAddresses[i]);
        }
        
        return prices;
    }
    
    /**
     * @dev Calculate the total USD value of a vault's reserves
     * @param vaultAddress Address of the vault contract
     * @return totalValue Total value in USD with 18 decimals
     */
    function getVaultValueUSD(address vaultAddress) public view returns (uint256) {
        require(vaultAddress != address(0), "Invalid vault address");
        
        IPairVault vault = IPairVault(vaultAddress);
        
        address token0 = vault.token0();
        address token1 = vault.token1();
        
        (uint256 reserve0, uint256 reserve1) = vault.getReserves();
        
        uint256 price0 = getTokenPrice(token0);
        uint256 price1 = getTokenPrice(token1);
        
        // Get token decimals
        uint8 decimals0 = IERC20(token0).decimals();
        uint8 decimals1 = IERC20(token1).decimals();
        
        // Calculate values (normalize to 18 decimals first, then multiply by price)
        uint256 value0;
        uint256 value1;
        
        if (decimals0 <= 18) {
            value0 = (reserve0 * 10**(18 - decimals0) * price0) / 1e18;
        } else {
            value0 = (reserve0 / 10**(decimals0 - 18) * price0) / 1e18;
        }
        
        if (decimals1 <= 18) {
            value1 = (reserve1 * 10**(18 - decimals1) * price1) / 1e18;
        } else {
            value1 = (reserve1 / 10**(decimals1 - 18) * price1) / 1e18;
        }
        
        return value0 + value1;
    }
    
    /**
     * @dev Calculate token value in USD
     * @param tokenAddress Address of the token
     * @param amount Amount of tokens (in token's native decimals)
     * @return value Value in USD with 18 decimals
     */
    function getTokenValueUSD(address tokenAddress, uint256 amount) public view returns (uint256) {
        uint256 price = getTokenPrice(tokenAddress);
        uint8 decimals = IERC20(tokenAddress).decimals();
        
        uint256 normalizedAmount;
        if (decimals <= 18) {
            normalizedAmount = amount * 10**(18 - decimals);
        } else {
            normalizedAmount = amount / 10**(decimals - 18);
        }
        
        return (normalizedAmount * price) / 1e18;
    }
    
    /**
     * @dev Set the maximum age for price data
     * @param _maxAge New maximum age in seconds
     */
    function setMaxAge(uint256 _maxAge) external onlyOwner {
        require(_maxAge > 0, "Max age must be greater than 0");
        require(_maxAge <= 24 hours, "Max age too large");
        
        uint256 oldMaxAge = maxAge;
        maxAge = _maxAge;
        
        emit MaxAgeUpdated(oldMaxAge, _maxAge);
    }
    
    /**
     * @dev Get all supported tokens
     * @return Array of supported token addresses
     */
    function getSupportedTokens() external view returns (address[] memory) {
        return supportedTokens;
    }
    
    /**
     * @dev Get number of supported tokens
     * @return Count of supported tokens
     */
    function getSupportedTokenCount() external view returns (uint256) {
        return supportedTokens.length;
    }
    
    /**
     * @dev Check if a token is supported and active
     * @param tokenAddress Address of the token
     * @return isSupported Whether the token is supported
     * @return isActive Whether the oracle is active
     */
    function getTokenStatus(address tokenAddress) external view returns (bool isSupported, bool isActive) {
        isSupported = isTokenSupported[tokenAddress];
        isActive = tokenOracles[tokenAddress].isActive;
    }
}
